def euclidean_distance(p1: Tuple[float, float, float], p2: Tuple[float, float, float]) -> float:
    #normalize
    dx1 = (p1[0] - p2[0]) / 50.0
    dx2 = (p1[1] - p2[1])
    dx3 = (p1[2] - p2[2])

    return math.sqrt(dx1 ** 2 + dx2 ** 2 + dx3 ** 2)